MasterdataImportResults = {
    init: async function(app, container, instance) {
        // extract the packaged data
        var dataPath = "DMS/Data/Masterdata/Processed/" + instance.Start.split("T")[0] + "/";
        var app = await api.get("ContentManagement/App(" + app.Id + ")");
        app.Config = JSON.parse(app.ConfigJson);
        await api.get(dataPath +  "Report-" + instance.Id + ".json").then((report) => {
            MasterdataImportResults.setupFileList(dataPath, report, $(".container[name=files]", container));
            MasterdataImportResults.setupImportSummary(app, report.Buyers, $(".container[name=buyers]", container));
            MasterdataImportResults.setupImportSummary(app, report.Suppliers, $(".container[name=suppliers]", container));
            MasterdataImportResults.setupImportSummary(app, report.Funders, $(".container[name=funders]", container));
            MasterdataImportResults.setupImportSummary(app, report.BuyerBuckets, $(".container[name=buyerBuckets]", container));
            MasterdataImportResults.setupImportSummary(app, report.SupplierBuckets, $(".container[name=supplierBuckets]", container));
            MasterdataImportResults.setupImportSummary(app, report.FunderBuckets, $(".container[name=funderBuckets]", container));
        }).catch((err) => {
            if(err.message) { notification.error(err.message); }
            else { notification.error(err.responseText); }
        });
        $("[name=tabs]", container).kendoTabStrip({ animation: { open: { effects: "fadeIn" } } });
    },

    setupFileList: function(dataPath, report, container) {
        var files = report.FilesProccessed.map(function(f) { return { name: f, link: api.apiRoot + dataPath + f + "?t=" + session.token }; });
        var links = files.map(f => "<a download='" + f.name + "' href='" + f.link + "'>" + f.name + "</a>");
        $("[name=list]", container).append(links.join("<br>"));
    },

    setupImportSummary: function(app, data, container) {
        container.append($("template[name=importSetSummary]").first().html());
        $("[name=imported]", container).append(data.Imported);
        $("[name=updated]", container).append(data.Updated);
        $("[name=deleted]", container).append(data.Deleted);
        $("[name=failures] > a", container).append(data.FailuresTotal);
        $("[name=failures] > a", container).on("click", () => MasterdataImportResults.openFailureDialog(app, data.Failures));
        $("[name=total]", container).append(data.Total);
    },

    openFailureDialog: function(app, failures) {
        // transform the source data to extract the key details
        var itemData = failures.map(function(i) { 
            return  {
                clientRef: MasterdataImportResults.getClientRef(i.Item, app.Config.B2B.SourceSystem),
                number: i.Item.Number,
                message: i.Message
            };
        });

        // build the dialog
        var dialog = new Dialog({ 
            name: "failedItemList", 
            title: "Failures", 
            width: "1000px", 
            height: "600px", 
            template: "<div name='grid' style='height: 600px;'></div>" 
        });

        dialog.init(function() {
            // build the grid
            var grid = new GridWidget($("[name=grid]", dialog.element), itemData);
            grid.editable = false;
            grid.groupable = false;
            grid.columns = [
                { field: "clientRef", type: "string", title:"Client Reference", width: 120 },
                { field: "number", type: "string", title:"Number", width: 120 },
                { field: "message", type: "string", title: "Problem" }
            ];
            grid.init();
        });
    },

    getClientRef: function(item, source) {
        return item;
    }
}
